package com.myassist.customer.ui;
import android.os.Bundle; import android.view.View; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import com.myassist.customer.network.*; import org.json.JSONObject;
public class CreateRequestActivity extends AppCompatActivity { EditText service,desc,pickup,dest; TextView error; ProgressBar progress; protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_create_request);service=findViewById(R.id.etService);desc=findViewById(R.id.etDesc);pickup=findViewById(R.id.etPickup);dest=findViewById(R.id.etDest);error=findViewById(R.id.tvError);progress=findViewById(R.id.progress);findViewById(R.id.btnSubmit).setOnClickListener(v->submit());} double[] parse(String s){String[] a=s.split(",");return new double[]{Double.parseDouble(a[0].trim()),Double.parseDouble(a[1].trim())};} void submit(){try{double[] p=parse(pickup.getText().toString()),d=parse(dest.getText().toString());JSONObject j=new JSONObject();j.put("service_type",service.getText().toString().trim());j.put("description",desc.getText().toString().trim());j.put("pickup",new JSONObject().put("address",pickup.getText().toString()).put("lat",p[0]).put("lng",p[1]));j.put("destination",new JSONObject().put("address",dest.getText().toString()).put("lat",d[0]).put("lng",d[1]));progress.setVisibility(View.VISIBLE);ApiService.run(ApiService.post("api/v1/customer/requests",j),x->x,new ApiService.Callback<JSONObject>(){public void onSuccess(JSONObject o){runOnUiThread(()->finish());}public void onError(ApiClient.ApiException e){runOnUiThread(()->{progress.setVisibility(View.GONE);error.setText(e.userMessage);error.setVisibility(View.VISIBLE);});}});}catch(Exception e){error.setText("Enter coordinates as latitude, longitude.");error.setVisibility(View.VISIBLE);}} }